import socket, time, paramiko

HOST, PORT = "127.0.0.1", 2222

def new_transport():
    sock = socket.create_connection((HOST, PORT), timeout=4)
    tr = paramiko.Transport(sock)
    tr.start_client(timeout=4)
    return tr

t0 = time.time()
try:
    tr = new_transport()
except Exception as e:
    print("CONNECT FAILED:", type(e).__name__, str(e))
    raise SystemExit(1)

print("REMOTE_VERSION:", tr.remote_version)
try:
    print("PREAUTH_BANNER:", repr(tr.get_banner()))
except Exception as e:
    print("banner read error:", type(e).__name__, str(e))

# Single auth_none probe: reveals which auth methods the server permits
try:
    tr.auth_none("probe-none")
    print("auth_none: UNEXPECTED SUCCESS (server permits none)")
except paramiko.BadAuthenticationType as e:
    print("ALLOWED_AUTH_METHODS:", sorted(e.allowed_types))
except Exception as e:
    print("auth_none exception:", type(e).__name__, str(e))
try:
    tr.close()
except Exception:
    pass

# Fresh connection: one synthetic password attempt, measure rejection latency
try:
    tr2 = new_transport()
    t1 = time.time()
    try:
        tr2.auth_password("synthetic-user", "synthetic-pass")
        print("PASSWORD AUTH: UNEXPECTED SUCCESS")
    except paramiko.AuthenticationException:
        print("PASSWORD AUTH: rejected in %.2fs" % (time.time() - t1))
    except Exception as e:
        print("PASSWORD AUTH error:", type(e).__name__, str(e), "(%.2fs)" % (time.time() - t1))
    tr2.close()
except Exception as e:
    print("second connection failed:", type(e).__name__, str(e))

print("TOTAL %.2fs" % (time.time() - t0))
