import socket, time, binascii, paramiko

HOST, PORT = "127.0.0.1", 2222

def connect():
    sock = socket.create_connection((HOST, PORT), timeout=4)
    tr = paramiko.Transport(sock)
    tr.start_client(timeout=4)
    return tr

def probe(user, pw):
    t0 = time.time()
    try:
        tr = connect()
    except Exception as e:
        print("connect failed:", type(e).__name__, str(e))
        return
    try:
        k = tr.get_remote_server_key()
        print("host_key: %s md5=%s" % (k.get_name(),
              binascii.hexlify(k.get_fingerprint()).decode()))
    except Exception as e:
        print("host_key unavailable:", type(e).__name__, str(e))
    try:
        tr.auth_password(user, pw)
        print("auth(%s): UNEXPECTED SUCCESS" % user)
    except paramiko.AuthenticationException:
        print("auth(%s): rejected (%.3fs)" % (user, time.time() - t0))
    except Exception as e:
        print("auth(%s): %s: %s (%.3fs)" % (user, type(e).__name__, str(e), time.time() - t0))
    try:
        tr.close()
    except Exception:
        pass

probe("audit", "definitely-wrong-pw")
probe("no-such-user-xyz", "definitely-wrong-pw")
PYEOF

